package nativeui

import (
	"fmt"
	"strings"

	"github.com/egoist/mygo/ui"
)

// useOwnerKeyButton offers the private key generated by the Create card to a
// form that must sign as the token owner. It is shown only while that key's
// token is the current subject and (for Transfer) the entered sender is the
// owner; otherwise it would sign for the wrong account.
func (a *App) useOwnerKeyButton(c *ui.Context, target *string, allow bool) {
	if !allow || a.token.ownerPriv == "" || a.token.ownerKeyTokenID == "" ||
		a.token.ownerKeyTokenID != strings.TrimSpace(a.token.tokenID) {
		return
	}
	if quietButton(c, "Use generated owner key").Clicked() {
		*target = a.token.ownerPriv
	}
}

func (a *App) tokenWrites(c *ui.Context) {
	tokenSubject(c, a.token.tokenID)
	tabs(c, &a.token.opTab, "Token actions", tr("Mint"), tr("Transfer"), tr("Approve"), tr("Transfer From"), tr("Burn"))
	switch a.token.opTab {
	case 0:
		formCard(c, "Mint", "Only the token owner can mint, and only for a mintable token.", func() {
			field(c, "To (base64 public key)", &a.token.mintTo)
			field(c, "Amount", &a.token.mintAmount)
			field(c, "Owner Private Key", &a.token.mintPriv)
			a.useOwnerKeyButton(c, &a.token.mintPriv, true)
			a.useSavedKeyButton(c, a.selectedTokenOwner(), &a.token.mintPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Mint", allSet(a.token.tokenID, a.token.mintTo, a.token.mintAmount, a.token.mintPriv)).Clicked() {
					a.mintToken()
				}
			})
		})

	case 1:
		formCard(c, "Transfer", "Move tokens from one account to another.", func() {
			field(c, "From (base64 public key)", &a.token.xFrom)
			field(c, "To (base64 public key)", &a.token.xTo)
			field(c, "Amount", &a.token.xAmount)
			field(c, "From Private Key", &a.token.xPriv)
			a.useOwnerKeyButton(c, &a.token.xPriv,
				strings.TrimSpace(a.token.xFrom) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.xFrom, &a.token.xPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Transfer", allSet(a.token.tokenID, a.token.xFrom, a.token.xTo, a.token.xAmount, a.token.xPriv)).Clicked() {
					a.transferToken()
				}
			})
		})

	case 2:
		formCard(c, "Approve", "Let a spender move up to an amount on the owner's behalf.", func() {
			field(c, "Owner (base64 public key)", &a.token.approveOwner)
			field(c, "Spender (base64 public key)", &a.token.approveTo)
			field(c, "Amount", &a.token.approveAmt)
			field(c, "Owner Private Key", &a.token.approvePriv)
			a.useOwnerKeyButton(c, &a.token.approvePriv,
				strings.TrimSpace(a.token.approveOwner) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.approveOwner, &a.token.approvePriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Approve", allSet(a.token.tokenID, a.token.approveOwner, a.token.approveTo, a.token.approveAmt, a.token.approvePriv)).Clicked() {
					a.approveToken()
				}
			})
		})

	case 3:
		formCard(c, "Transfer From", "Spend an allowance the owner granted.", func() {
			field(c, "Owner (base64 public key)", &a.token.fromOwner)
			field(c, "To (base64 public key)", &a.token.fromTo)
			field(c, "Amount", &a.token.fromAmount)
			fieldHint(c, "Spender public key (optional)", "Used only to find a key saved for this session.", &a.token.fromSpender)
			field(c, "Spender Private Key", &a.token.fromPriv)
			a.useSavedKeyButton(c, a.token.fromSpender, &a.token.fromPriv)
			ui.Row(c).Children(func() {
				if primaryButton(c, "Transfer From", allSet(a.token.tokenID, a.token.fromOwner, a.token.fromTo, a.token.fromAmount, a.token.fromPriv)).Clicked() {
					a.transferFromToken()
				}
			})
		})

	case 4:
		formCard(c, "Burn", "Destroy tokens from an account. This cannot be undone.", func() {
			field(c, "From (base64 public key)", &a.token.burnFrom)
			field(c, "Amount", &a.token.burnAmount)
			field(c, "Owner Private Key", &a.token.burnPriv)
			a.useOwnerKeyButton(c, &a.token.burnPriv,
				strings.TrimSpace(a.token.burnFrom) == a.selectedTokenOwner())
			a.useSavedKeyButton(c, a.token.burnFrom, &a.token.burnPriv)
			burnReady := allSet(a.token.tokenID, a.token.burnFrom, a.token.burnAmount, a.token.burnPriv)
			ui.Row(c).Children(func() {
				// A destructive action carries the danger style, and the
				// confirmation still stands between it and the write.
				burn := dangerButton(c, "Burn…").Disabled(!burnReady).Bind(&a.token.burnTrigger)
				if burn.Clicked() {
					a.token.askBurn = true
				}
			})
		})

	}
}

// The write handlers below read only the inputs of the section that invoked
// them. Sharing one address field between sections (as the page once did for
// Approve and Allowance) signs for an account the operator typed somewhere
// else and cannot see from the form they used.
func (a *App) mintToken() {
	privateKey := strings.TrimSpace(a.token.mintPriv)
	tokenID, to := strings.TrimSpace(a.token.tokenID), strings.TrimSpace(a.token.mintTo)
	amount := strings.TrimSpace(a.token.mintAmount)
	if rejectIncomplete(&a.token.status, "Token ID, recipient, amount, and private key are required.", tokenID, to, amount, privateKey) {
		return
	}
	owner := a.selectedTokenOwner()
	a.runWrite("Minting…", func() func() {
		err := a.services.MintToken(tokenID, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(owner, privateKey)
				// A signing key that was used successfully is not kept on screen:
				// the next write needs its own key, and a shared display should not
				// retain the secret.
				a.token.mintPriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) transferToken() {
	privateKey := strings.TrimSpace(a.token.xPriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	from, to := strings.TrimSpace(a.token.xFrom), strings.TrimSpace(a.token.xTo)
	amount := strings.TrimSpace(a.token.xAmount)
	if rejectIncomplete(&a.token.status, "Token ID, sender, recipient, amount, and private key are required.", tokenID, from, to, amount, privateKey) {
		return
	}
	a.runWrite("Transferring…", func() func() {
		err := a.services.TransferToken(tokenID, from, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(from, privateKey)
				a.token.xPriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) approveToken() {
	privateKey := strings.TrimSpace(a.token.approvePriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	owner, spender := strings.TrimSpace(a.token.approveOwner), strings.TrimSpace(a.token.approveTo)
	amount := strings.TrimSpace(a.token.approveAmt)
	if rejectIncomplete(&a.token.status, "Token ID, owner, spender, amount, and private key are required.", tokenID, owner, spender, amount, privateKey) {
		return
	}
	a.runWrite("Approving…", func() func() {
		err := a.services.ApproveToken(tokenID, owner, spender, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(owner, privateKey)
				a.token.approvePriv = ""
				a.refreshToken()
			}
		}
	})
}

func (a *App) transferFromToken() {
	privateKey := strings.TrimSpace(a.token.fromPriv)
	tokenID := strings.TrimSpace(a.token.tokenID)
	owner, to := strings.TrimSpace(a.token.fromOwner), strings.TrimSpace(a.token.fromTo)
	amount := strings.TrimSpace(a.token.fromAmount)
	if rejectIncomplete(&a.token.status, "Token ID, owner, recipient, amount, and spender private key are required.", tokenID, owner, to, amount, privateKey) {
		return
	}
	spender := a.token.fromSpender
	a.runWrite("Transferring…", func() func() {
		err := a.services.TransferFromToken(tokenID, owner, to, amount, privateKey)
		return func() {
			a.token.status = wrapErr(err)
			if err == nil {
				a.rememberSuccessfulKey(spender, privateKey)
				a.token.fromPriv = ""
				a.refreshToken()
			}
		}
	})
}

// renderBurnDialog shows the confirmation while a burn is pending. The burn
// runs only when the operator deliberately picks "Burn", the same gate the
// CLI's --confirm flag is; Enter alone cancels.
func (a *App) renderBurnDialog(c *ui.Context) {
	if !a.token.askBurn {
		return
	}
	// Name the amount and the account in the question: a bare "Burn tokens?"
	// asked the operator to trust whichever fields the form held, and a wrong
	// amount is irreversible.
	detail := tr("Burning destroys the amount permanently. This cannot be undone.")
	amount := strings.TrimSpace(a.token.burnAmount)
	owner := strings.TrimSpace(a.token.burnFrom)
	if amount != "" || owner != "" {
		detail = fmt.Sprintf(
			"Burn %s from %s? The tokens are destroyed permanently and cannot be recovered.",
			valueOr(amount), valueOr(owner))
	}
	switch destructiveConfirm(c, &a.token.askBurn, tr("Burn tokens?"), detail, tr("Burn"),
		a.token.burnTrigger, a.token.burnTrigger) {
	case destructiveConfirmed:
		tokenID := strings.TrimSpace(a.token.tokenID)
		privateKey := strings.TrimSpace(a.token.burnPriv)
		if !allSet(tokenID, owner, amount, privateKey) {
			a.token.status = errorStatus("Token ID, source account, amount, and private key are required.")
			return
		}
		a.runWrite("Burning…", func() func() {
			err := a.services.BurnToken(tokenID, owner, amount, privateKey)
			return func() {
				a.token.status = wrapErr(err)
				if err == nil {
					a.rememberSuccessfulKey(owner, privateKey)
					a.token.burnPriv = ""
					a.refreshToken()
				}
			}
		})
	}
}
